import React, { useState } from "react";
import {
  changeEmail,
  changePassword,
  createCharacter,
  deleteCharacter,
  saveBio,
  saveDisplayName,
  setDefaultCharacter,
  setGamerTag,
  signOut,
  updateCharacterBio,
} from "../lib/db";
import { T, inputStyle } from "../theme";
import { Avatar, Btn, Field, H1, hash } from "../ui/primitives";

export function Profile({ me, setMe, chars, setChars, go }) {
  const [tab, setTab] = useState("general");
  const [copied, setCopied] = useState(false);
  const [newName, setNewName] = useState("");

  const [editingTag, setEditingTag] = useState(false);
  const [tagBase, setTagBase] = useState(me.tag?.split("-")[0] ?? "");
  const [tagDigits, setTagDigits] = useState(me.tag?.split("-")[1] ?? "");
  const [tagError, setTagError] = useState(null);
  const [tagBusy, setTagBusy] = useState(false);

  const saveTag = async () => {
    setTagBusy(true); setTagError(null);
    try {
      const tag = await setGamerTag(tagBase, tagDigits);
      setMe((m) => ({ ...m, tag }));
      setEditingTag(false);
    } catch (e) {
      setTagError(e.message);
    } finally {
      setTagBusy(false);
    }
  };

  const addChar = async () => {
    const n = newName.trim(); if (!n) return;
    setNewName("");
    try {
      const row = await createCharacter(me.id, n);
      setChars((cs) => [...cs, row]);
    } catch (e) { console.error("could not create character", e); }
  };

  const chooseDefaultChar = async (charId) => {
    setMe((m) => ({ ...m, defaultCharacterId: charId }));
    try {
      await setDefaultCharacter(me.id, charId);
    } catch (e) { console.error("could not set default character", e); }
  };
  return (
    <div className="pf-in" style={{ maxWidth: 620 }}>
      <H1>Profile</H1>

      <div style={{ display: "flex", gap: 4, borderBottom: "1px solid " + T.edge, marginBottom: 24 }}>
        {[["general", "General"], ["account", "Account"]].map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} className="pf-btn"
            style={{ background: "none", border: "none", cursor: "pointer", padding: "10px 14px",
              fontFamily: T.mono, fontSize: 12, color: tab === k ? T.bone : T.boneDim,
              boxShadow: tab === k ? "inset 0 -2px 0 " + T.ochre : "none" }}>
            {label}
          </button>
        ))}
      </div>

      {tab === "general" && (
      <>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 26 }}>
        <button onClick={() => go("avatar")} className="pf-btn"
          style={{ background: "none", border: "none", padding: 0, cursor: "pointer", borderRadius: "50%" }}
          title="Change your profile picture">
          <Avatar name={me.name} tag={me.tag} size={62}
            src={me.avatarMode === "generated" ? me.avatarUrl : undefined}
            bgColor={me.avatarMode === "default" ? me.avatarBgColor : undefined}
            bgColor2={me.avatarMode === "default" ? me.avatarBgColor2 : undefined}
            letterColor={me.avatarMode === "default" ? me.avatarLetterColor : undefined} />
        </button>
        <div>
          <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 3 }}>your gamer tag</div>
          <button className="pf-btn"
            onClick={() => { navigator.clipboard?.writeText(me.tag); setCopied(true); setTimeout(() => setCopied(false), 1400); }}
            style={{ background: "none", border: "none", padding: 0, cursor: "pointer", fontFamily: T.mono, fontSize: 19, letterSpacing: ".1em", color: T.ochre }}>
            {me.tag}
          </button>
          <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, height: 14, marginTop: 3 }}>{copied ? "copied" : "tap to copy"}</div>
        </div>
      </div>

      <Field label="Gamer Tag" hint="The name half and the 4-digit number can both be changed. Whatever you pick has to be free as a whole.">
        {!editingTag ? (
          <Btn kind="ghost" onClick={() => { setTagBase(me.tag?.split("-")[0] ?? ""); setTagDigits(me.tag?.split("-")[1] ?? ""); setEditingTag(true); }}>
            Change gamer tag
          </Btn>
        ) : (
          <div>
            <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
              <input style={{ ...inputStyle, flex: 1 }} value={tagBase}
                onChange={(e) => setTagBase(e.target.value.replace(/[^a-zA-Z0-9]/g, ""))}
                placeholder="lily" />
              <span style={{ fontFamily: T.mono, color: T.boneDim }}>-</span>
              <input style={{ ...inputStyle, width: 80 }} value={tagDigits}
                onChange={(e) => setTagDigits(e.target.value.replace(/[^0-9]/g, "").slice(0, 4))}
                placeholder="4356" />
            </div>
            {tagError && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "0 0 8px" }}>{tagError}</p>}
            <div style={{ display: "flex", gap: 8 }}>
              <Btn kind="solid" disabled={tagBusy || !tagBase || tagDigits.length !== 4} onClick={saveTag}>
                {tagBusy ? "\u2026" : "Save"}
              </Btn>
              <Btn kind="ghost" onClick={() => setEditingTag(false)}>Cancel</Btn>
            </div>
          </div>
        )}
      </Field>

      <Field label="Username" hint="How your published worlds are credited. You can change it any time from here — each check costs a couple of cents.">
        {me.username ? (
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ fontFamily: T.mono, fontSize: 16, color: T.ochre, letterSpacing: ".02em" }}>
              @{me.username}
            </div>
            <Btn kind="ghost" onClick={() => go("username", { next: "profile" })}>Change</Btn>
          </div>
        ) : (
          <Btn onClick={() => go("username", { next: "profile" })}>Choose a username</Btn>
        )}
      </Field>

      <Field label="Display name" hint="What friends see.">
        <input style={inputStyle} value={me.name}
          onChange={(e) => setMe({ ...me, name: e.target.value })}
          onBlur={(e) => saveDisplayName(me.id, e.target.value.trim() || "New player")
            .catch((err) => console.error("could not save name", err))} />
      </Field>

      <Field label="Description" hint="A little about yourself.">
        <textarea style={{ ...inputStyle, resize: "vertical", lineHeight: 1.6 }} rows={4} value={me.bio ?? ""}
          onChange={(e) => setMe({ ...me, bio: e.target.value })}
          onBlur={(e) => saveBio(me.id, e.target.value.trim())
            .catch((err) => console.error("could not save bio", err))}
          placeholder="Tell people a little about yourself" />
      </Field>

      <div style={{ borderTop: `1px solid ${T.edge}`, paddingTop: 24, marginTop: 10 }}>
        <h2 style={{ fontFamily: T.serif, fontSize: 20, fontWeight: 400, margin: "0 0 4px" }}>Characters</h2>
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.55, margin: "0 0 18px" }}>
          A character is a name and a face you bring into a world. Each world keeps separate progress for them,
          because no two worlds count health or items the same way.
        </p>
        {chars.map((c, i) => {
          const isDefault = (me.defaultCharacterId ?? chars[0]?.id) === c.id;
          return (
          <div key={c.id} style={{ display: "flex", gap: 12, alignItems: "center", padding: "12px 0", borderBottom: `1px solid ${T.edge}` }}>
            <button className="pf-btn" onClick={() => chooseDefaultChar(c.id)}
              title="Play as this character"
              style={{ width: 16, height: 16, borderRadius: "50%", flexShrink: 0, padding: 0, cursor: "pointer",
                border: "1px solid " + (isDefault ? T.ochre : T.edge),
                background: isDefault ? T.ochre : "transparent" }} />
            <div style={{ width: 34, height: 34, borderRadius: 2, flexShrink: 0,
              background: `linear-gradient(140deg, hsl(${hash(c.name) % 360} 26% 26%), hsl(${(hash(c.name) + 80) % 360} 30% 42%))` }} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontFamily: T.serif, fontSize: 16 }}>
                {c.name}{i === 0 && <span style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, marginLeft: 8 }}>default</span>}
              </div>
              <input value={c.bio ?? ""} placeholder="one line about them"
                onChange={(e) => setChars(chars.map((x) => x.id === c.id ? { ...x, bio: e.target.value } : x))}
                onBlur={(e) => updateCharacterBio(c.id, e.target.value)
                  .catch((err) => console.error("could not save bio", err))}
                style={{ ...inputStyle, border: "none", padding: 0, fontSize: 13.5, color: T.boneDim, background: "none" }} />
            </div>
            {i !== 0 && (
              <Btn kind="ghost" onClick={async () => {
                setChars(chars.filter((x) => x.id !== c.id));
                try { await deleteCharacter(c.id); } catch (e) { console.error("could not delete", e); }
              }}>remove</Btn>
            )}
          </div>
          );
        })}
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, lineHeight: 1.6, margin: "4px 0 0" }}>
          The dot picks who you play as — this replaces choosing a character each time you open a game.
        </p>
        <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
          <input value={newName} onChange={(e) => setNewName(e.target.value)} onKeyDown={(e) => e.key === "Enter" && addChar()}
            placeholder="New character's name" style={inputStyle} />
          <Btn onClick={addChar}>Add</Btn>
        </div>
      </div>

      <div style={{ borderTop: `1px solid ${T.edge}`, paddingTop: 22, marginTop: 28,
        display: "flex", gap: 10, flexWrap: "wrap" }}>
        <Btn onClick={() => signOut()}>Sign out</Btn>
      </div>
      </>
      )}

      {tab === "account" && (() => {
        // Navigate to the proper SettingsPage immediately rather than
        // rendering the old inline AccountTab which was a lower-quality
        // duplicate of the same content.
        go("settings");
        return null;
      })()}
    </div>
  );
}

function AccountTab() {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordBusy, setPasswordBusy] = useState(false);
  const [passwordError, setPasswordError] = useState(null);
  const [passwordSaved, setPasswordSaved] = useState(false);

  const [newEmail, setNewEmail] = useState("");
  const [emailBusy, setEmailBusy] = useState(false);
  const [emailError, setEmailError] = useState(null);
  const [emailSaved, setEmailSaved] = useState(false);

  const savePassword = async () => {
    if (newPassword.length < 6) { setPasswordError("At least 6 characters."); return; }
    if (newPassword !== confirmPassword) { setPasswordError("Those two don't match."); return; }
    setPasswordBusy(true); setPasswordError(null);
    try {
      await changePassword(newPassword);
      setNewPassword(""); setConfirmPassword("");
      setPasswordSaved(true);
      setTimeout(() => setPasswordSaved(false), 2000);
    } catch (e) {
      setPasswordError(e.message);
    } finally {
      setPasswordBusy(false);
    }
  };

  const saveEmail = async () => {
    if (!newEmail.trim()) return;
    setEmailBusy(true); setEmailError(null);
    try {
      await changeEmail(newEmail.trim());
      setEmailSaved(true);
    } catch (e) {
      setEmailError(e.message);
    } finally {
      setEmailBusy(false);
    }
  };

  return (
    <div>
      <Field label="Change password" hint="At least 6 characters.">
        <div style={{ display: "grid", gap: 8, maxWidth: 320 }}>
          <input type="password" style={inputStyle} placeholder="New password"
            value={newPassword} onChange={(e) => setNewPassword(e.target.value)} />
          <input type="password" style={inputStyle} placeholder="Confirm new password"
            value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} />
        </div>
        {passwordError && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "8px 0 0" }}>{passwordError}</p>}
        <div style={{ marginTop: 10, display: "flex", alignItems: "center", gap: 10 }}>
          <Btn kind="solid" disabled={passwordBusy || !newPassword || !confirmPassword} onClick={savePassword}>
            {passwordBusy ? "\u2026" : "Save password"}
          </Btn>
          {passwordSaved && <span style={{ fontFamily: T.mono, fontSize: 11, color: T.moss }}>saved</span>}
        </div>
      </Field>

      <Field label="Change email" hint="A confirmation link is sent before this actually takes effect — it won't change immediately.">
        {emailSaved ? (
          <p style={{ fontFamily: T.mono, fontSize: 12.5, color: T.moss, lineHeight: 1.6 }}>
            Check your inbox for a confirmation link to finish the change.
          </p>
        ) : (
          <>
            <input type="email" style={{ ...inputStyle, maxWidth: 320 }} placeholder="new@email.com"
              value={newEmail} onChange={(e) => setNewEmail(e.target.value)} />
            {emailError && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "8px 0 0" }}>{emailError}</p>}
            <div style={{ marginTop: 10 }}>
              <Btn kind="solid" disabled={emailBusy || !newEmail.trim()} onClick={saveEmail}>
                {emailBusy ? "\u2026" : "Send confirmation"}
              </Btn>
            </div>
          </>
        )}
      </Field>
    </div>
  );
}

