import React, { useEffect, useState } from "react";
import { T, grid, inputStyle } from "../theme";
import { useNarrow } from "../hooks";
import { Btn } from "../ui/primitives";
import { TrailerHero } from "../ui/TrailerHero";
import { GameCard } from "./Browse";
import { sortWorlds } from "../lib/db";
import { loadActiveTrailer, joinWaitlist } from "../lib/marketing";

const STEPS = [
  ["Describe it", "One paragraph is enough. A drowned cathedral, a market at the edge of a desert, a house that remembers its owners."],
  ["Watch it get drawn", "Rooms, characters, props and items are generated as scenes — built from your description, in a consistent style."],
  ["Publish and share", "Drafts stay private until you say otherwise. Publish, and it appears in the catalog with your name on it."],
];

export function Landing({ games = [], go }) {
  const narrow = useNarrow();
  const [trailer, setTrailer] = useState(null);
  useEffect(() => { loadActiveTrailer().then(setTrailer).catch(() => {}); }, []);

  // Staff picks first, in the admin's order (1 on top). Anything not picked comes
  // after them, most played first, so the section is never short of games.
  const featured = sortWorlds(games.filter((g) => g.published), "staff").slice(0, narrow ? 4 : 8);

  const scrollToWaitlist = () => {
    const el = document.getElementById("waitlist");
    if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
  };

  return (
    <div className="pf-in">

      {trailer ? (
        <TrailerHero trailer={trailer}>
          <HeroCopy onJoin={scrollToWaitlist} go={go} />
        </TrailerHero>
      ) : (
        <div className="pf-card" style={{ marginBottom: 34, padding: narrow ? 0 : "8px 0" }}>
          <HeroCopy onJoin={scrollToWaitlist} go={go} wide />
        </div>
      )}

      <div style={{ marginTop: 48, marginBottom: 14, fontFamily: T.serif, fontSize: 19 }}>
        How a world gets made
      </div>
      <div style={{ display: "grid", gap: 20,
        gridTemplateColumns: narrow ? "minmax(0,1fr)" : "repeat(3, minmax(0,1fr))" }}>
        {STEPS.map(([title, body], i) => (
          <div key={title}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 6 }}>
              {String(i + 1).padStart(2, "0")}
            </div>
            <div style={{ fontFamily: T.serif, fontSize: 17, marginBottom: 6 }}>{title}</div>
            <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.55, color: T.boneDim, margin: 0 }}>
              {body}
            </p>
          </div>
        ))}
      </div>

      {featured.length > 0 && (
        <>
          <div style={{ marginTop: 52, marginBottom: 14, display: "flex", alignItems: "baseline", gap: 12 }}>
            <div style={{ fontFamily: T.serif, fontSize: 19 }}>Built on Ascentery</div>
            <button className="pf-btn" onClick={() => go("browse")}
              style={{ background: "none", border: "none", padding: 0, cursor: "pointer",
                fontFamily: T.mono, fontSize: 11.5, color: T.ochre }}>
              browse everything →
            </button>
          </div>
          <div style={grid}>
            {featured.map((g) => (
              <GameCard key={g.id} g={g} go={go}
                onClick={() => go("game", { id: g.id, authorUsername: g.authorUsername, slug: g.slug, from: "landing" })} />
            ))}
          </div>
        </>
      )}

      <Waitlist />
    </div>
  );
}

function HeroCopy({ onJoin, go, wide }) {
  return (
    <>
      <div className="pf-title"
        style={{ fontFamily: T.serif, fontSize: wide ? 34 : 30, lineHeight: 1.12, marginBottom: 10 }}>
        Worlds you imagine, drawn for you.
      </div>
      <p style={{ fontFamily: T.serif, fontSize: 16.5, lineHeight: 1.55, color: T.boneDim,
        margin: "0 0 18px", maxWidth: wide ? 620 : undefined }}>
        Ascentery turns a paragraph into a playable, illustrated world. Play what other
        people have built — or describe your own and watch it appear, room by room.
      </p>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        <Btn kind="solid" onClick={onJoin}>Request an invite</Btn>
        <Btn onClick={() => go("browse")}>Browse games</Btn>
      </div>
    </>
  );
}

function Waitlist() {
  const narrow = useNarrow();
  const [email, setEmail] = useState("");
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState(null);

  const submit = async () => {
    setBusy(true); setError(null);
    try {
      await joinWaitlist({ email, note });
      setDone(true);
    } catch (e) {
      setError(e?.message ?? "Something went wrong. Try again in a moment.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div id="waitlist" style={{ marginTop: 52, paddingTop: 22, borderTop: `1px solid ${T.edge}`, maxWidth: 560 }}>
      <div style={{ fontFamily: T.serif, fontSize: 19, marginBottom: 6 }}>Request an invite</div>
      {done ? (
        <p style={{ fontFamily: T.serif, fontSize: 15.5, lineHeight: 1.6, color: T.boneDim, margin: 0 }}>
          You are on the list. We will email you when a place opens up — one message, no newsletter.
        </p>
      ) : (
        <>
          <p style={{ fontFamily: T.serif, fontSize: 15.5, lineHeight: 1.6, color: T.boneDim, margin: "0 0 14px" }}>
            Leave an address and we will write when one opens. If you tell us what you would
            build, invites go out to the most interesting answers first.
          </p>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 10 }}>
            <input value={email} onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && email && !busy) submit(); }}
              type="email" placeholder="you@example.com"
              style={{ ...inputStyle, flex: 1, minWidth: narrow ? "100%" : 260,
                fontFamily: T.mono, fontSize: 13, padding: "9px 11px" }} />
          </div>
          <textarea value={note} onChange={(e) => setNote(e.target.value)}
            rows={3} maxLength={500} placeholder="What would you build? (optional)"
            style={{ ...inputStyle, width: "100%", resize: "vertical",
              fontFamily: T.serif, fontSize: 15, padding: "9px 11px", marginBottom: 12 }} />
          <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
            <Btn kind="solid" onClick={submit} disabled={busy || !email}>
              {busy ? "Sending…" : "Join the waitlist"}
            </Btn>
            {error && <span style={{ fontFamily: T.mono, fontSize: 11.5, color: T.ochre }}>{error}</span>}
          </div>
        </>
      )}
    </div>
  );
}
