import React, { useEffect, useRef, useState } from "react";
import { T } from "../theme";
import { useNarrow } from "../hooks";

function parseSource(url) {
  if (!url) return { kind: "none" };
  const u = String(url).trim();
  if (/\.(mp4|webm|mov|m4v)(\?|$)/i.test(u)) return { kind: "file", src: u };
  const yt = u.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([\w-]{6,})/i);
  if (yt) {
    const id = yt[1];
    return {
      kind: "embed",
      autoSrc: `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&mute=1&loop=1&playlist=${id}&controls=0&modestbranding=1&rel=0&playsinline=1`,
      soundSrc: `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&controls=1&rel=0&playsinline=1`,
    };
  }
  const vm = u.match(/vimeo\.com\/(?:video\/)?(\d+)/i);
  if (vm) {
    const id = vm[1];
    return {
      kind: "embed",
      autoSrc: `https://player.vimeo.com/video/${id}?autoplay=1&muted=1&loop=1&background=1`,
      soundSrc: `https://player.vimeo.com/video/${id}?autoplay=1&muted=0&loop=0`,
    };
  }
  return { kind: "embed", autoSrc: u, soundSrc: u };
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener?.("change", sync);
    return () => mq.removeEventListener?.("change", sync);
  }, []);
  return reduced;
}

// Exact copy of Play.jsx's FullscreenIcon — same SVG paths, strokeWidth,
// viewBox and everything.
function FullscreenIcon({ active }) {
  const d = active
    ? "M9 3H4v5M15 3h5v5M9 21H4v-5M15 21h5v-5"
    : "M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5";
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d={d} />
    </svg>
  );
}

export function TrailerHero({ trailer, ratio = 0.5625, children }) {
  const narrow = useNarrow();
  const reduced = usePrefersReducedMotion();
  const [withSound, setWithSound] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const videoRef = useRef(null);
  const frameRef = useRef(null);

  const src = parseSource(trailer?.sourceUrl);
  if (src.kind === "none") return null;

  const posterOnly = (narrow || reduced) && !withSound;

  useEffect(() => {
    const onChange = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    document.addEventListener("webkitfullscreenchange", onChange);
    return () => {
      document.removeEventListener("fullscreenchange", onChange);
      document.removeEventListener("webkitfullscreenchange", onChange);
    };
  }, []);

  const toggleFullscreen = () => {
    if (document.fullscreenElement) {
      document.exitFullscreen?.();
    } else {
      frameRef.current?.requestFullscreen?.() ??
      frameRef.current?.webkitRequestFullscreen?.();
    }
  };

  const play = () => {
    setWithSound(true);
    const v = videoRef.current;
    if (v) { v.muted = false; v.currentTime = 0; v.play?.().catch(() => {}); }
  };

  // Use aspect-ratio directly rather than the padding-top trick —
  // it works the same way but doesn't require position:absolute children,
  // which means the iframe fills the container without needing objectFit
  // (which doesn't apply to iframes and was causing the black side bars).
  const frameStyle = {
    position: "relative",
    width: "100%",
    aspectRatio: `${1 / ratio}`,   // e.g. "1.777" for 16:9
    background: "#000",            // black behind video, not T.ground
    border: `1px solid ${T.edge}`,
    borderRadius: 2,
    overflow: "hidden",
  };

  const fillStyle = {
    position: "absolute", inset: 0,
    width: "100%", height: "100%",
    border: 0,
  };

  // Bleed 4px on each side — pushes black letterbox bars outside the
  // clipped frame for both self-hosted video and embedded iframes.
  const bleedStyle = {
    position: "absolute",
    top: -4, left: -4, right: -4, bottom: -4,
    width: "calc(100% + 8px)",
    height: "calc(100% + 8px)",
    border: 0,
  };

  return (
    <div className="pf-card"
      style={{
        display: "grid",
        gridTemplateColumns: narrow ? "minmax(0,1fr)" : "minmax(0,1.4fr) minmax(0,1fr)",
        gap: 24, marginBottom: 34, alignItems: "center",
      }}>

      <div ref={frameRef} style={frameStyle}>
        {posterOnly ? (
          trailer.posterUrl
            ? <img src={trailer.posterUrl} alt="" style={{ ...fillStyle, objectFit: "cover" }} />
            : <div style={{ ...fillStyle, background: T.edge }} />
        ) : src.kind === "file" ? (
          <video
            ref={videoRef}
            src={src.src}
            poster={trailer.posterUrl || undefined}
            autoPlay muted={!withSound} loop={!withSound} playsInline
            controls={withSound}
            preload="metadata"
            style={{ ...bleedStyle, objectFit: "cover" }} />
        ) : (
          <iframe
            src={withSound ? src.soundSrc : src.autoSrc}
            title={trailer.label || "Trailer"}
            allow="autoplay; fullscreen; picture-in-picture"
            allowFullScreen
            style={bleedStyle} />
        )}

        {/* Fullscreen toggle — exact same style as Play.jsx room image button */}
        <button
          onClick={toggleFullscreen}
          title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
          style={{
            position: "absolute", top: 8, right: 8, zIndex: 5,
            background: "transparent", border: "none", padding: 6,
            cursor: "pointer", display: "inline-flex",
            color: T.bone, opacity: 0.75, lineHeight: 0,
          }}>
          <FullscreenIcon active={isFullscreen} />
        </button>

        {/* Watch with sound / Play button — bottom left */}
        {!withSound && (
          <button
            onClick={play}
            className="pf-btn"
            style={{
              position: "absolute", left: 12, bottom: 12,
              display: "flex", alignItems: "center", gap: 8,
              background: "rgba(0,0,0,.62)", color: T.bone,
              border: `1px solid ${T.edge}`, borderRadius: 2,
              padding: "8px 12px", cursor: "pointer",
              fontFamily: T.mono, fontSize: 11, letterSpacing: ".04em",
            }}>
            <svg width="10" height="12" viewBox="0 0 10 12" aria-hidden>
              <path d="M0 0l10 6-10 6z" fill="currentColor" />
            </svg>
            {posterOnly ? "Play trailer" : "Watch with sound"}
            {trailer.durationLabel ? ` · ${trailer.durationLabel}` : ""}
          </button>
        )}
      </div>

      <div>{children}</div>
    </div>
  );
}
